const manifest = {
  profile: { rows: 4, missing: 'mapped', outliers: 'dispositioned' },
  views: { distributions: true, trends: true, comparisons: true, funnel: true, cohort: true },
  honesty: { trapsCaught: 3 },
  story: { takeaways: 3, recommendation: true },
  caveats: { samples: true, windows: true, methods: true },
};
const checks = [
  ['profile complete', manifest.profile.rows > 0 && !!manifest.profile.missing],
  ['all views present', ['distributions', 'trends', 'comparisons', 'funnel', 'cohort'].every((k) => manifest.views[k])],
  ['honesty evidenced', manifest.honesty.trapsCaught >= 3],
  ['story argues', manifest.story.takeaways >= 1 && manifest.story.recommendation],
  ['caveats bound', manifest.caveats.samples && manifest.caveats.windows && manifest.caveats.methods],
];
for (const [label, ok] of checks) console.log((ok ? 'PASS ' : 'FAIL ') + label);
console.log(checks.every(([, ok]) => ok) ? 'report shippable' : 'report BLOCKED');

